1	import { useState } from "react";
2	import { Input } from "@/components/ui/input";
3	import { Button } from "@/components/ui/button";
4	import { Checkbox } from "@/components/ui/checkbox";
5	
6	export default function App() {
7	  const [todo, setTodo] = useState("");
8	  const [todos, setTodos] = useState([
9	    { text: "Write a new blog post.", completed: false },
10	    { text: "Pick up laundry.", completed: false },
11	    { text: "Die.", completed: false },
12	  ]);
13	
14	  const handleAddTodo = () => {
15	    if (todo.trim()) {
16	      setTodos([...todos, { text: todo, completed: false }]);
17	      setTodo("");
18	    }
19	  };
20	
21	  const handleToggleComplete = (index) => {
22	    const updatedTodos = todos.map((todo, i) =>
23	      i === index ? { ...todo, completed: !todo.completed } : todo
24	    );
25	    setTodos(updatedTodos);
26	  };
27	
28	  return (
29	    <div className="flex flex-col items-center min-h-screen bg-gray-100">
30	      <div className="w-full max-w-md p-6 bg-white shadow-md rounded-lg mt-16">
31	        <h1 className="text-2xl font-bold text-center mb-6">Another ToDo App</h1>
32	        <div className="flex items-center mb-4">
33	          <Input
34	            type="text"
35	            placeholder="Add a ToDo"
36	            value={todo}
37	            onChange={(e) => setTodo(e.target.value)}
38	            className="flex-grow border border-gray-300 rounded-l-md px-3 py-2"
39	          />
40	          <Button
41	            onClick={handleAddTodo}
42	            className="bg-blue-500 text-white px-4 py-2 rounded-r-md hover:bg-blue-600"
43	          >
44	            Add
45	          </Button>
46	        </div>
47	        <div className="space-y-2">
48	          {todos.map((todo, index) => (
49	            <div
50	              key={index}
51	              className="flex items-center border-b border-gray-200 pb-2 last:border-b-0"
52	            >
53	              <Checkbox
54	                checked={todo.completed}
55	                onChange={() => handleToggleComplete(index)}
56	                className="mr-2"
57	              />
58	              <span
59	                className={`flex-grow ${
60	                  todo.completed ? "line-through text-gray-500" : ""
61	                }`}
62	              >
63	                {todo.text}
64	              </span>
65	            </div>
66	          ))}
67	        </div>
68	      </div>
69	    </div>
70	  );
71	}
